{
  "states": [
    "Initial",
    "Session Established",
    "Terminated"
  ],
  "transitions": [
    {
      "from": "Initial",
      "event": "INVITE",
      "action": "Send 100 Trying, forward INVITE",
      "to": "Session Negotiation"
    },
    {
      "from": "Session Negotiation",
      "event": "180 Ringing",
      "action": "Send Ringing response",
      "to": "Session Negotiation"
    },
    {
      "from": "Session Negotiation",
      "event": "200 OK",
      "action": "Send ACK, establish media session",
      "to": "Session Established"
    },
    {
      "from": "Session Established",
      "event": "BYE",
      "action": "Send 200 OK",
      "to": "Terminated"
    }
  ]
}

{
  "states": ["early", "confirmed"],
  "transitions": [
    {
      "from": "early",
      "event": "2xx final response",
      "action": "transition to confirmed",
      "to": "confirmed"
    },
    {
      "from": "early",
      "event": "other responses or no response",
      "action": "terminate early dialog",
      "to": "terminated"
    }
  ]
}

{
  "states": [
    "Early Dialog",
    "Confirmed Dialog",
    "Terminated Dialog"
  ],
  "transitions": [
    {
      "from": "Early Dialog",
      "event": "2xx response received",
      "action": "Transition to confirmed state, recompute route set",
      "to": "Confirmed Dialog"
    },
    {
      "from": "Early Dialog",
      "event": "Non-2xx final response received",
      "action": "Terminate early dialog",
      "to": "Terminated Dialog"
    },
    {
      "from": "Early Dialog",
      "event": "64*T1 seconds after first 2xx",
      "action": "Consider transaction completed, terminate remaining early dialogs",
      "to": "Terminated Dialog"
    },
    {
      "from": "Confirmed Dialog",
      "event": "ACK sent",
      "action": "",
      "to": "Confirmed Dialog"
    },
    {
      "from": "Confirmed Dialog",
      "event": "BYE request sent",
      "action": "Terminate dialog",
      "to": "Terminated Dialog"
    }
  ]
}

{
  "states": ["Confirmed Dialog", "Early Dialog"],
  "transitions": [
    {
      "from": "Confirmed Dialog",
      "event": "BYE request",
      "action": "Terminate session and dialog",
      "to": "Terminated"
    },
    {
      "from": "Early Dialog",
      "event": "BYE request",
      "action": "",
      "to": "Terminated"
    },
    {
      "from": "Confirmed Dialog",
      "event": "non-2xx final response",
      "action": "Terminate session and dialog",
      "to": "Terminated"
    },
    {
      "from": "Early Dialog",
      "event": "non-2xx final response",
      "action": "Terminate session and dialog",
      "to": "Terminated"
    },
    {
      "from": "Confirmed Dialog",
      "event": "CANCEL",
      "action": "Force non-2xx response (e.g., 487)",
      "to": "Terminated"
    }
  ]
}

{
  "states": [
    "calling",
    "Proceeding",
    "Completed",
    "Terminated"
  ],
  "transitions": [
    {
      "from": "calling",
      "event": "provisional response",
      "action": "pass to TU",
      "to": "Proceeding"
    },
    {
      "from": "calling",
      "event": "300-699 response",
      "action": "pass to TU, generate ACK, send ACK",
      "to": "Completed"
    },
    {
      "from": "calling",
      "event": "Timer B fires",
      "action": "inform TU timeout",
      "to": "Terminated"
    },
    {
      "from": "calling",
      "event": "Transport Error",
      "action": "inform TU, transition to Terminated",
      "to": "Terminated"
    },
    {
      "from": "Proceeding",
      "event": "300-699 response",
      "action": "pass to TU, generate ACK, send ACK",
      "to": "Completed"
    },
    {
      "from": "Proceeding",
      "event": "Timer F fires",
      "action": "inform TU timeout",
      "to": "Terminated"
    },
    {
      "from": "Proceeding",
      "event": "Transport Error",
      "action": "inform TU, transition to Terminated",
      "to": "Terminated"
    },
    {
      "from": "Completed",
      "event": "Timer D fires",
      "action": "",
      "to": "Terminated"
    },
    {
      "from": "Completed",
      "event": "retransmission of final response",
      "action": "re-pass ACK to transport",
      "to": "Completed"
    },
    {
      "from": "Completed",
      "event": "2xx response",
      "action": "pass to TU",
      "to": "Terminated"
    },
    {
      "from": "Terminated",
      "event": "",
      "action": "",
      "to": "Terminated"
    }
  ]
}

